sys_script_client.script:
function onSubmit() {
    var percStr = g_form.getValue("academic_percentage");
    if (percStr !== "") {
        var perc = parseFloat(percStr);
        if (isNaN(perc) || perc < 0 || perc > 100) {
            g_form.addErrorMessage("Academic percentage must be a valid number between 0 and 100.");
            return false;
        }
    }
    var incStr = g_form.getValue("annual_family_income");
    if (incStr !== "") {
        var inc = parseFloat(incStr);
        if (isNaN(inc) || inc < 0) {
            g_form.addErrorMessage("Annual family income must be a non-negative number.");
            return false;
        }
    }
    return true;
}
